let current=0;
try{const saved=localStorage.getItem('erode-expo-language');const i=languages.findIndex(x=>x.code===saved);if(i>=0)current=i;}catch{}
export const getLang=()=>languages[current];
export const t=(key)=>copy[key]?.[current]??key;
export function setLang(code){const i=languages.findIndex(x=>x.code===code);if(i<0)return;current=i;document.documentElement.lang=code;try{localStorage.setItem('erode-expo-language',code);}catch{}window.dispatchEvent(new CustomEvent('localechange'));}
export const money=n=>new Intl.NumberFormat(getLang().locale,{style:'currency',currency:'INR',maximumFractionDigits:0}).format(n);
export const date=iso=>new Intl.DateTimeFormat(getLang().locale,{day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Kolkata'}).format(new Date(iso+'T12:00:00+05:30'));
